import{z as d,x as B,o as n,c as p,q as i,j as r,D as e,d as t,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"速度竞赛与狙击","description":"","frontmatter":{"title":"速度竞赛与狙击","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/speed-race-sniping.md","filePath":"quant/speed-race-sniping.md","lastUpdated":1791063341000}'),A={name:"quant/speed-race-sniping.md"};function u(m,a,c,h,f,_){const s=B("Mermaid");return n(),p("div",null,[a[2]||(a[2]=i('<h1 id="速度竞赛与狙击" tabindex="-1">速度竞赛与狙击 <a class="header-anchor" href="#速度竞赛与狙击" aria-label="Permalink to &quot;速度竞赛与狙击&quot;">​</a></h1><div class="epigraph"><p>狙击是在别人来得及撤过时报价之前把它吃掉。速度的私人价值等于这份期权的期望租金；社会价值在竞赛均衡里被耗散在线和机柜上。</p><footer>—— Budish, Cramton and Shim, Quarterly Journal of Economics, 2015；新闻交易与速度见 Foucault, Hombert and Roşu, News Trading and Speed, Review of Financial Studies, 2016</footer></div><p><a href="/quant/frequent-batch-auction">频繁批量拍卖</a>给出设计回应。缺口是把连续市场上的速度写成可分析的策略：谁在听新闻、谁在挂单、均衡延迟投到哪一步。Foucault、Hombert 与 Roşu（2016）分析新闻交易与速度；Biais、Foucault 与 Moinas（2015）给出均衡快速交易。本课写狙击机制，不重复 FBA 的批长讨论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公共新闻有两个观察者：做市商要撤，套利/新闻交易者要吃。两者都投资速度。若吃的人更快，发生狙击，价差必须预先加宽以补偿期望被捡；若撤的人更快，过时报价消失，狙击利润下降，但挂单寿命更短、有效深度更闪。问题是对称投资速度时，市场质量落在哪一侧，以及速度差异（而不是绝对速度）为何才是租金来源。</p><p>Foucault–Hombert–Roşu 强调：更快接收新闻的交易者会选择更激进的订单，价格发现加快，但慢的流动性提供者受损。发现与流动性可以反方向，这与 Bloomfield–O&#39;Hara 对透明的权衡同构，只是不对称从「看见身份」换成「看见新闻的时间」。</p><h3 id="相关市场是狙击的基础设施" tabindex="-1">相关市场是狙击的基础设施 <a class="header-anchor" href="#相关市场是狙击的基础设施" aria-label="Permalink to &quot;相关市场是狙击的基础设施&quot;">​</a></h3><p>现货挂单相对期货中点过时，是最干净的公共信号。跨市场监控速度因此比单市场线速更重要。碎片化倍增需要监控的场所，军备成本上升。这不是<a href="/quant/market-fragmentation">市场分割</a>课的 NBBO 会计，而是延迟结构如何创造期权。</p><p><span class="marginnote">Kyle 知情者的优势是 \\(V\\)，速度知情者的优势是同一条公共新闻的时钟。把 HFT 都叫做 Kyle 式内幕，会把合法的公开信息处理与私有公司信息混为一谈。执法关心的是后者与操纵，不是所有低延迟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两玩家投资延迟 \\(d\\)，成本 \\(c(d)\\) 凸。新闻泊松到达，过时报价价值为 \\(s\\) 量级。先到者赢得 \\(s\\)，均衡直到 \\(c&#39;(d)\\) 等于期望赢得的边际。租金耗散：总速度支出约等于期权期望值。价差把 \\(s\\) 预先加进报价，最终由流动性需求者支付军备。</p><p>比较：禁止托管、统一随机延迟、批量拍卖、速度颠簸，都是在改变 \\(d\\) 的可行集或改变「先到者通吃」的支付。下一设计单元会逐个看场所规则；本课只保留：任何仍让先到者独赢 \\(s\\) 的连续协议，都会重建竞赛。</p><p><span class="marginnote">数字实例：假设某品种一年被狙击吃掉的期望租金约 100 万元。均衡里竞赛者花在专线、机柜、FPGA 上的总支出会逼近这个数——比如三家各投 30 万、40 万、30 万，谁也没多赚，钱全变成了设备商与交易所的收入。这就是「租金耗散」：奖品还在，只是没人拿到手。</span></p>',13)),(n(),r(l,null,{default:e(()=>[o(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20News%5B%22%E5%85%AC%E5%85%B1%E6%96%B0%E9%97%BB%22%5D%20--%3E%20MM%5B%22%E5%81%9A%E5%B8%82%E5%95%86%E6%92%A4%E5%8D%95%22%5D%0A%20%20News%20--%3E%20Sn%5B%22%E6%96%B0%E9%97%BB%E4%BA%A4%E6%98%93%E8%80%85%E5%B8%82%E4%BB%B7%22%5D%0A%20%20MM%20--%3E%20Win%5B%22%E8%B0%81%E5%85%88%E5%88%B0%3A%20%E6%92%A4%E6%8E%89%20vs%20%E5%90%83%E6%8E%89%22%5D%0A%20%20Sn%20--%3E%20Win%0A%20%20Win%20--%3E%20Rent%5B%22%E7%A7%9F%E9%87%91%E8%80%97%E6%95%A3%E5%9C%A8%E9%80%9F%E5%BA%A6%E4%B8%8A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"狙击把 Foucault 的被捡从「下一离散期」压到「下一微秒」。限价期权的时间价值不再由基本波动主导，而由相对延迟主导。于是出现看似悖论的现象：基础波动不大，但价差仍宽、撤单仍频——因为相关市场的一跳就足以创造 \\(s\\)。微观结构不变量课会问不同资产上 \\(s\\) 如何随成交量缩放；这里只需承认 \\(s\\) 是内生的制度租金。",-1)),(n(),r(l,null,{default:e(()=>[o(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Threat%5B%22%E7%8B%99%E5%87%BB%E5%A8%81%E8%83%81%20s%22%5D%20--%3E%20Spread%5B%22%E5%81%9A%E5%B8%82%E5%95%86%E9%A2%84%E5%85%88%E5%8A%A0%E5%AE%BD%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20Spread%20--%3E%20Pay%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E9%9C%80%E6%B1%82%E8%80%85%E6%8C%89%E5%AE%BD%E4%BB%B7%E5%B7%AE%E6%88%90%E4%BA%A4%22%5D%0A%20%20Pay%20--%3E%20Subsidy%5B%22%E4%BB%B7%E5%B7%AE%E6%94%B6%E5%85%A5%E8%A1%A5%E8%B4%B4%E5%81%9A%E5%B8%82%E5%95%86%E7%9A%84%E9%80%9F%E5%BA%A6%E6%8A%95%E8%B5%84%22%5D%0A%20%20Subsidy%20--%3E%20MMfast%5B%22%E6%92%A4%E5%8D%95%E6%9B%B4%E5%BF%AB%E3%80%81%E6%8C%82%E5%8D%95%E5%AF%BF%E5%91%BD%E6%9B%B4%E7%9F%AD%22%5D%0A%20%20MMfast%20--%3E%20Depth%5B%22%E6%9C%89%E6%95%88%E6%B7%B1%E5%BA%A6%E5%8F%98%E8%96%84%E5%8F%98%E9%97%AA%22%5D%0A%20%20Depth%20--%3E%20Threat%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">这张闭环图回答一个问题：竞赛没参赛的人为什么也要付钱。答案是把「速度税」写进价差——普通投资者每笔多付的价差，沿途补贴了双方的速度军备，最终由不参赛的流动性需求者买单。</span></p><p><span class="marginnote">术语翻译：「限价期权」指挂一张限价单等于免费送出一张期权——市场朝不利方向跳时，你的单会被先成交（行权给了对方）。这张期权的「时间价值」原本由波动率决定，现在主要由相对延迟决定：对方比你快多少，决定它多快被行权。</span></p><p><span class="marginnote">常见误区：初学者容易以为「只要我够快就能赚狙击的钱」。实际上如果所有参赛者都一样快，军备支出恰好耗散掉全部期望租金，净利润趋近于零；真正的赢家只有卖线路的、卖机柜的和收托管费的场所。</span></p><p>对策略噪声：非知情者无法参加竞赛，他们要么付更宽价差，要么把单交给也能竞赛的中介。中介化是速度的分配结果。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>并非所有 HFT 利润都是狙击。库存做市、合约间对冲、提供深度，可以有正社会价值。实证要把「新闻窗口的吃单」与「无新闻时的双边挂单」分开，这是 Menkveld / Brogaard 的工作。随机延迟若只加在入场、不加在行情，可能只是把竞赛改道。法律上的幌骚与这里的合法新闻交易，分界在是否有真实交易意图与是否虚假挂单。</p><p><span class="marginnote">把「谁快谁赢」当成公平，忽略了过时报价往往是正在提供流动性的慢参与者。公平取决于协议，不是取决于延迟的自然排序。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>狙击是对过时报价的速度竞赛；相对延迟产生租金，绝对速度在对称均衡里被耗散。</li><li>发现可以加快而流动性受损；相关市场是主要公共信号源。</li><li>连续先到者通吃的支付一保留，竞赛就会重建。</li><li>出处：Budish, Cramton and Shim, <em>QJE</em>, 2015；Foucault, Hombert and Roşu, <em>RFS</em>, 2016；Biais, Foucault and Moinas, <em>Journal of Financial Economics</em>, 2015。</li></ul>',9))])}const F=d(A,[["render",u]]);export{b as __pageData,F as default};
